nner&utm_campaign=upgrade_agency';?><div class="mga-ai-notice-wrap">    <form method="post" action="options.php">        <?php settings_fields( 'megagovern_notice_settings' ); ?>        <div class="mga-row mga-row-2col">            <!-- LEFT COLUMN – MAIN SETTINGS -->            <div>                <div class="mga-card">                    <div class="mga-card-header">                        <h3 class="mga-card-title">                            <?php echo wp_kses( megagovern_ai_notice_icon( 'bell', '16' ), $megagovern_allowed_svg ); ?>                            <?php esc_html_e( 'AI Transparency Notice', 'megagovern' ); ?>                        </h3>                        <?php if ( ! $megagovern_is_pro && ! $megagovern_is_agency ) : ?>                            <span class="mga-pill mga-pill--warn">                                <?php echo wp_kses( megagovern_ai_notice_icon( 'lock', '12' ), $megagovern_allowed_svg ); ?>                                <?php esc_html_e( 'Free', 'megagovern' ); ?>                            </span>                        <?php else : ?>                            <span class="mga-pill mga-pill--ok">                                <?php echo wp_kses( megagovern_ai_notice_icon( 'check', '12' ), $megagovern_allowed_svg ); ?>                                <?php esc_html_e( 'Pro', 'megagovern' ); ?>                            </span>                        <?php endif; ?>                    </div>                    <div class="mga-card-body">                        <!-- Free Version Notice -->                        <?php if ( ! $megagovern_is_pro && ! $megagovern_is_agency ) : ?>                            <div class="mga-notice mga-notice--info" style="margin-bottom:16px;">                                <div class="mga-notice-content">                                    <strong><?php esc_html_e( 'Free Version — Default Blue Theme', 'megagovern' ); ?></strong>                                